toolUseResult.originalFile:
/* CommandGuide — interactive guide artifacts */

.cmd-guide {
  margin-top: 16px;
  margin-bottom: 12px;
  border: 2px solid #c7d2fe;
  border-radius: 16px;
  overflow: hidden;
  background: #fafbff;
}

.cmd-guide__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: linear-gradient(135deg, #eef2ff, #e0e7ff);
  border-bottom: 1px solid #c7d2fe;
}

.cmd-guide__header-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.cmd-guide__icon {
  font-size: 20px;
  color: var(--color-primary, #2563eb);
}

.cmd-guide__title {
  font-size: 18px;
  font-weight: 700;
  color: #1e293b;
}

.cmd-guide__controls {
  display: flex;
  gap: 6px;
}

.cmd-guide__toggle,
.cmd-guide__dismiss {
  font-size: 15px;
  font-weight: 600;
  padding: 5px 12px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  min-height: 32px;
}

.cmd-guide__toggle {
  background: var(--color-primary, #2563eb);
  color: white;
}

.cmd-guide__toggle:hover { opacity: 0.9; }

.cmd-guide__dismiss {
  background: #e2e8f0;
  color: #64748b;
  padding: 5px 10px;
}

.cmd-guide__dismiss:hover { background: #cbd5e1; }

.cmd-guide__body {
  padding: 16px;
}

.cmd-guide__desc {
  font-size: 17px;
  color: #475569;
  margin: 0 0 16px;
  line-height: 1.5;
}

.cmd-guide__steps {
  list-style: none;
  counter-reset: guide-step;
  padding: 0;
  margin: 0;
}

.cmd-guide__step {
  counter-increment: guide-step;
  margin-bottom: 20px;
  padding-left: 40px;
  position: relative;
}

.cmd-guide__step::before {
  content: counter(guide-step);
  position: absolute;
  left: 0;
  top: 0;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--color-primary, #2563eb);
  color: white;
  font-size: 16px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cmd-guide__step:last-child {
  margin-bottom: 0;
}

.cmd-guide__step-text {
  font-size: 18px;
  line-height: 1.5;
  color: #1e293b;
  margin-bottom: 8px;
}

/* Command block */
.cmd-guide__command-block {
  background: #1e293b;
  border-radius: 10px;
  overflow: hidden;
  margin-top: 8px;
}

.cmd-guide__command-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  gap: 10px;
}

.cmd-guide__code {
  font-family: 'SF Mono', 'Fira Code', 'Cascadia Code', monospace;
  font-size: 15px;
  color: #a5f3fc;
  white-space: pre-wrap;
  word-break: break-all;
  flex: 1;
}

.cmd-guide__command-actions {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}

.cmd-guide__copy-btn,
.cmd-guide__run-btn {
  font-size: 14px;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  min-height: 34px;
  white-space: nowrap;
}

.cmd-guide__copy-btn {
  background: #334155;
  color: #94a3b8;
}

.cmd-guide__copy-btn:hover {
  background: #475569;
  color: white;
}

.cmd-guide__run-btn {
  background: #16a34a;
  color: white;
}

.cmd-guide__run-btn:hover {
  background: #15803d;
}

.cmd-guide__run-btn:disabled {
  background: #64748b;
  cursor: wait;
}

/* Command output */
.cmd-guide__output {
  font-family: 'SF Mono', 'Fira Code', monospace;
  font-size: 13px;
  color: #d1d5db;
  background: #0f172a;
  padding: 12px 14px;
  margin: 0;
  border-top: 1px solid #334155;
  white-space: pre-wrap;
  word-break: break-all;
  max-height: 200px;
  overflow-y: auto;
}

.cmd-guide__output--error {
  color: #fca5a5;
  border-top-color: #991b1b;
}

/* Step notes */
.cmd-guide__note {
  font-size: 15px;
  color: #64748b;
  font-style: italic;
  margin: 6px 0 0;
  line-height: 1.4;
}

/* Responsive */
@media (max-width: 480px) {
  .cmd-guide__command-row {
    flex-direction: column;
    align-items: stretch;
  }
  .cmd-guide__command-actions {
    justify-content: flex-end;
  }
}

